20	impl Parse for Meta {
21	    fn parse(input: ParseStream) -> Result<Self> {
22	        Ok(Self {
23	            name: parse_string::<kw::name>(input)?,
24	            span: parse_key_value::<kw::span, syn::Expr>(input)?,
25	        })
26	    }
27	}
