29	fn create(meta: Meta, mut item: syn::ItemFn) -> TokenStream {
30	    let name = meta.name.unwrap_or_else(|| item.sig.ident.to_string());
31	    let construct = match meta.span.as_ref() {
32	        Some(span) => quote! { with_span(#name, Some(#span.into_raw())) },
33	        None => quote! { new(#name) },
34	    };
35	
